<script lang="ts">
 import {displayText} from './display-text.mjs';
 import {enhance} from '$app/forms';import DatePicker from './DatePicker.svelte';import BoundaryMap from './BoundaryMap.svelte';
 let {data,enhanced,busy}:{data:any,enhanced:any,busy:boolean}=$props();
 let selected=$state(''),open=$state(false),editBoundary=$state(false),boundary=$state('');
 const zones=$derived(data.tables.talazo_zones);
 const zone=$derived(zones.find((z:any)=>z.id===selected)||zones[0]);
 const record=$derived(data.tables.talazo_monitoring.find((m:any)=>m.zone_id===zone?.id&&m.environment===data.environment));
</script>
<section class="p-card"><p class="p-kicker">FIELD & SEASON CHANGES</p><h2>Keep your growing season current.</h2><p>Request crop, planting-date or boundary changes. Talazo reviews capacity before updating satellite monitoring. Uncertain updates stay reserved until verified.</p>
 {#if zone}<details bind:open><summary>Request a field change</summary>{#if open}<label class="p-field">Growing area<select bind:value={selected} onchange={()=>{editBoundary=false;boundary='';}}><option value="">Choose a field</option>{#each zones as z}<option value={z.id}>{z.name}</option>{/each}</select></label>
 {#key zone.id}{#if record&&['active','awaiting','paused'].includes(record.status)}<form method="POST" action="?/requestChange" use:enhance={enhanced} class="p-form single"><input type="hidden" name="monitoring" value={record.id}/><label class="p-field">Crop name<input name="crop" value={zone.crop_entered_name||zone.crop_name} maxlength="120" required/></label><DatePicker name="sowing" label="Planting date" value={zone.sowing_date||''}/><label class="p-caption"><input type="checkbox" bind:checked={editBoundary} onchange={()=>{if(editBoundary&&!boundary)boundary=JSON.stringify(zone.boundary);}}/> Change the field boundary too</label>{#if editBoundary}<BoundaryMap bind:value={boundary}/><input type="hidden" name="boundary" value={boundary||JSON.stringify(zone.boundary)}/>{/if}<button class="p-button" disabled={busy}>Submit for review</button></form>{:else}<p>Activate or reconcile this field before requesting changes.</p>{/if}{/key}{/if}</details>{/if}
 {#each data.changes||[] as change}{@const m=data.tables.talazo_monitoring.find((v:any)=>v.id===change.monitoring_id)}{@const z=zones.find((v:any)=>v.id===m?.zone_id)}
 <article><h3>{z?.name||'Field'} · {change.state}</h3><p>{change.previous.crop_name} → {change.desired.crop_name} · Planting: {change.desired.sowing_date||'Not recorded'}</p><p class="p-caption">Requested area: {(change.desired.area_sqm/10000).toFixed(4)} ha · Submitted {new Date(change.created_at).toLocaleDateString('en-GB')}</p>{#if change.error}<p role="status">{displayText(change.error)}</p>{/if}
 {#if change.state==='pending'}<div class="buttons">{#if data.admin}<form method="POST" action="?/approveChange" use:enhance={enhanced}><input type="hidden" name="change" value={change.id}/><button class="p-button" disabled={busy}>Approve & update provider</button></form>{/if}<form method="POST" action="?/cancelChange" use:enhance={enhanced}><input type="hidden" name="change" value={change.id}/><button class="p-button subtle" disabled={busy}>Cancel request</button></form></div>
 {:else if data.admin&&['applying','uncertain'].includes(change.state)}<form method="POST" action="?/reconcileChange" use:enhance={enhanced}><input type="hidden" name="change" value={change.id}/><button class="p-button subtle" disabled={busy}>Verify provider result</button></form>
 {:else if change.state==='completed'}<details><summary>Previous season record</summary><p>{change.previous.crop_name} · Planted {change.previous.sowing_date||'Not recorded'} · {(change.previous.area_sqm/10000).toFixed(4)} ha</p><p class="p-caption">{change.previous_observation?'Previous observation snapshot retained with this change.':'No earlier observation snapshot was available.'}</p></details>{/if}</article>{/each}
</section>
<style>summary{cursor:pointer;font-weight:600;padding:12px 0}article{border-top:1px solid #dce2d4;padding:20px 0}h3{font-size:19px}.buttons{display:flex;gap:12px;flex-wrap:wrap}.p-form.single{display:flex;flex-direction:column;gap:18px;max-width:900px}input[type=checkbox]{width:auto}</style>
